# Implement Rect, Sides, Measurement primitives

## Objective
Implement the layout primitives used throughout ftui.

## Rect (Rectangle)
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Self {
        Self { x, y, width, height }
    }

    pub fn contains(&self, x: u16, y: u16) -> bool {
        x >= self.x && x < self.x + self.width &&
        y >= self.y && y < self.y + self.height
    }

    pub fn intersection(&self, other: &Self) -> Self {
        let x = self.x.max(other.x);
        let y = self.y.max(other.y);
        let right = (self.x + self.width).min(other.x + other.width);
        let bottom = (self.y + self.height).min(other.y + other.height);

        if right > x && bottom > y {
            Self::new(x, y, right - x, bottom - y)
        } else {
            Self::default()  // Empty rect
        }
    }

    pub fn inner(&self, margin: Sides) -> Self {
        Self::new(
            self.x + margin.left,
            self.y + margin.top,
            self.width.saturating_sub(margin.left + margin.right),
            self.height.saturating_sub(margin.top + margin.bottom),
        )
    }

    pub fn is_empty(&self) -> bool {
        self.width == 0 || self.height == 0
    }

    pub fn area(&self) -> u32 {
        self.width as u32 * self.height as u32
    }
}

