use ftui_core::{GestureRecognizer, GestureConfig, SemanticEvent};

pub struct Program<M: Model> {
    model: M,
    gesture_recognizer: GestureRecognizer,
    // ... existing fields
}

impl<M: Model> Program<M> {
    pub fn with_gesture_config(mut self, config: GestureConfig) -> Self {
        self.gesture_recognizer = GestureRecognizer::new(config);
        self
    }

    fn process_event(&mut self, event: Event) {
        let now = Instant::now();

        // Generate semantic events
        let semantic_events = self.gesture_recognizer.process(&event, now);

        // Deliver semantic events first (higher priority)
        for semantic in semantic_events {
            if let Some(msg) = M::Message::from_semantic(semantic) {
                let cmd = self.model.update(msg);
                self.process_cmd(cmd);
            }
        }

        // Then deliver raw event
        let msg = M::Message::from(event);
        let cmd = self.model.update(msg);
        self.process_cmd(cmd);
    }
}
```

