    pub allocation: TickAllocation,
    pub fallback_divisor: u64,     // default: 5
    pub min_observations: u64,     // default: 20
    pub decay_factor: f64,         // default: 0.85
    pub decay_interval: u64,       // default: 500
    pub smoothing_alpha: f64,      // default: 1.0
    pub persistence_path: Option<PathBuf>,
    pub auto_save_interval: u64,   // default: 3000 (ticks)
}
```

### Testing

