Queue system for managing multiple concurrent notifications.

## Requirements
- FIFO queue with max visible limit
- Stacking behavior when multiple toasts
- Priority queue for urgent notifications
- Deduplication of identical messages

## Proposed API

```rust
use std::collections::VecDeque;

/// Notification queue manager
pub struct NotificationQueue {
    queue: VecDeque<QueuedNotification>,
    visible: Vec<Toast>,
    config: QueueConfig,
    dedup_window: Duration,
    recent_hashes: HashMap<u64, Instant>,
}

#[derive(Clone)]
pub struct QueueConfig {
    pub max_visible: usize,          // Max toasts shown at once (default: 3)
    pub max_queued: usize,           // Max pending in queue (default: 10)
    pub default_duration: Duration,  // Auto-dismiss time (default: 5s)
    pub position: ToastPosition,     // Anchor position (e.g., TopRight)
    pub stagger_offset: u16,         // Vertical spacing (default: 1)
    pub dedup_window_ms: u64,        // Dedup identical messages (default: 1000)
}

struct QueuedNotification {
    toast: Toast,
    priority: NotificationPriority,
    created_at: Instant,
    content_hash: u64,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum NotificationPriority {
    Low = 0,
    Normal = 1,
    High = 2,
    Urgent = 3,  // Urgent jumps to front
}

impl NotificationQueue {
    pub fn new(config: QueueConfig) -> Self;

    /// Add notification to queue
    pub fn push(&mut self, toast: Toast, priority: NotificationPriority) -> bool;

    /// Dismiss specific notification
    pub fn dismiss(&mut self, id: ToastId);

    /// Dismiss all notifications
    pub fn dismiss_all(&mut self);

    /// Process tick, returns actions to perform
    pub fn tick(&mut self, delta: Duration) -> Vec<QueueAction>;

    /// Get currently visible toasts
    pub fn visible(&self) -> &[Toast];

    /// Queue depth
    pub fn pending_count(&self) -> usize;

    // --- Internal ---

    fn dedup_check(&mut self, hash: u64) -> bool {
        let now = Instant::now();
        // Clean old hashes
        self.recent_hashes.retain(|_, t| now.duration_since(*t) < self.dedup_window);
        // Check if duplicate
        if self.recent_hashes.contains_key(&hash) {
            return false;  // Duplicate
        }
        self.recent_hashes.insert(hash, now);
        true
    }

    fn promote_from_queue(&mut self) {
        while self.visible.len() < self.config.max_visible {
            if let Some(queued) = self.queue.pop_front() {
                self.visible.push(queued.toast);
            } else {
                break;
            }
        }
    }
}

pub enum QueueAction {
    Show(Toast),
    Hide(ToastId),
    UpdatePosition(ToastId, Position),
}
```

## Stacking Behavior

```rust
fn calculate_positions(&self) -> Vec<(ToastId, Position)> {
    let mut y = match self.config.position {
        ToastPosition::TopRight | ToastPosition::TopCenter | ToastPosition::TopLeft => 1,
        _ => self.screen_height - 1,
    };

    self.visible.iter().map(|toast| {
        let pos = (toast.id, Position::new(self.toast_x(toast), y));
        y += toast.height() + self.config.stagger_offset;
        pos
    }).collect()
}
```

