## Goal
Cache layout computation results and skip re-computation when constraints haven't changed.

## Background
Layout computation (constraint solving, flex distribution) is currently done every frame, even when:
- Terminal size is unchanged
- Widget constraints are unchanged
- Content dimensions are unchanged

For complex layouts with many nested containers, this is wasteful.

## Cache Design
```rust
use std::collections::HashMap;
use std::hash::{Hash, Hasher, DefaultHasher};

/// Key for layout cache - must be hashable
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct LayoutCacheKey {
    /// Available area for layout
    area: Rect,
    /// Fingerprint of constraints
    constraints_hash: u64,
    /// Direction of layout
    direction: Direction,
    /// Fingerprint of intrinsic sizes (if using FitContent)
    intrinsics_hash: Option<u64>,
}

/// Cached layout result
#[derive(Clone, Debug)]
struct CachedLayoutEntry {
    /// Computed chunk rectangles
    chunks: Vec<Rect>,
    /// Generation when cached
    generation: u64,
    /// Access count for LRU
    access_count: u32,
}

/// Layout computation cache
pub struct LayoutCache {
    entries: HashMap<LayoutCacheKey, CachedLayoutEntry>,
    generation: u64,
    max_entries: usize,
    // Statistics
    hits: u64,
    misses: u64,
}

impl LayoutCache {
    pub fn new(max_entries: usize) -> Self {
        Self {
            entries: HashMap::with_capacity(max_entries),
            generation: 0,
            max_entries,
            hits: 0,
            misses: 0,
        }
    }

    /// Get cached layout or compute and cache
    pub fn get_or_compute<F>(
        &mut self,
        key: LayoutCacheKey,
        compute: F,
    ) -> Vec<Rect>
    where
        F: FnOnce() -> Vec<Rect>,
    {
        // Check cache
        if let Some(entry) = self.entries.get_mut(&key) {
            if entry.generation == self.generation {
                self.hits += 1;
                entry.access_count += 1;
                return entry.chunks.clone();
            }
        }

        // Cache miss
        self.misses += 1;
        let chunks = compute();

        // Evict if full
        if self.entries.len() >= self.max_entries {
            self.evict_lru();
        }

        self.entries.insert(key, CachedLayoutEntry {
            chunks: chunks.clone(),
            generation: self.generation,
            access_count: 1,
        });

        chunks
    }

    /// Invalidate all entries
    pub fn invalidate_all(&mut self) {
        self.generation = self.generation.wrapping_add(1);
    }

    /// Get statistics
    pub fn stats(&self) -> LayoutCacheStats {
        LayoutCacheStats {
            entries: self.entries.len(),
            hits: self.hits,
            misses: self.misses,
            hit_rate: if self.hits + self.misses > 0 {
                self.hits as f64 / (self.hits + self.misses) as f64
            } else {
                0.0
            },
        }
    }

    fn evict_lru(&mut self) {
        if let Some(key) = self.entries.iter()
            .min_by_key(|(_, e)| e.access_count)
            .map(|(k, _)| *k)
        {
            self.entries.remove(&key);
        }
    }
}

#[derive(Debug, Clone)]
pub struct LayoutCacheStats {
    pub entries: usize,
    pub hits: u64,
    pub misses: u64,
    pub hit_rate: f64,
}
```

## Fingerprinting
```rust
impl LayoutCacheKey {
    pub fn new(
        area: Rect,
        constraints: &[Constraint],
        direction: Direction,
        intrinsics: Option<&[SizeConstraints]>,
    ) -> Self {
        Self {
            area,
            constraints_hash: Self::hash_constraints(constraints),
            direction,
            intrinsics_hash: intrinsics.map(Self::hash_intrinsics),
        }
    }

    fn hash_constraints(constraints: &[Constraint]) -> u64 {
        let mut hasher = DefaultHasher::new();
        constraints.hash(&mut hasher);
        hasher.finish()
    }

    fn hash_intrinsics(intrinsics: &[SizeConstraints]) -> u64 {
        let mut hasher = DefaultHasher::new();
        for ic in intrinsics {
            ic.min.hash(&mut hasher);
            ic.preferred.hash(&mut hasher);
            ic.max.hash(&mut hasher);
        }
        hasher.finish()
    }
}
```

## Integration with Layout
```rust
impl Layout {
    /// Split area with caching
    pub fn split_cached(
        &self,
        area: Rect,
        cache: &mut LayoutCache,
    ) -> Vec<Rect> {
        let key = LayoutCacheKey::new(
            area,
            &self.constraints,
            self.direction,
            None, // No intrinsics for non-FitContent
        );

        cache.get_or_compute(key, || self.split(area))
    }

    /// Split area with measurer and caching
    pub fn split_with_measurer_cached<F>(
        &self,
        area: Rect,
        cache: &mut LayoutCache,
        measurer: F,
    ) -> Vec<Rect>
    where
        F: Fn(usize) -> SizeConstraints,
    {
        // Collect intrinsics for FitContent items
        let intrinsics: Vec<SizeConstraints> = (0..self.constraints.len())
            .map(|i| measurer(i))
            .collect();

        let key = LayoutCacheKey::new(
            area,
            &self.constraints,
            self.direction,
            Some(&intrinsics),
        );

        cache.get_or_compute(key, || {
            self.split_with_measurer(area, |i| intrinsics[i])
        })
    }
}
```

## Performance Impact
- **Without cache**: Layout computed every frame (100+ μs for complex layouts)
- **With cache**: Hash + lookup + clone (< 1 μs)
- **Expected hit rate**: 95%+ for typical UIs

## Testing Requirements

### Unit Tests (crates/ftui-layout/src/cache/tests.rs)
```rust
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cache_returns_same_result() {
        let mut cache = LayoutCache::new(100);
        let key = LayoutCacheKey::new(
            Rect::new(0, 0, 80, 24),
            &[Constraint::Percentage(50), Constraint::Percentage(50)],
            Direction::Horizontal,
            None,
        );

        let mut compute_count = 0;
        let compute = || {
            compute_count += 1;
            vec\![Rect::new(0, 0, 40, 24), Rect::new(40, 0, 40, 24)]
        };

        let r1 = cache.get_or_compute(key, compute);
        let r2 = cache.get_or_compute(key, || panic\!("should not call"));

        assert_eq\!(r1, r2);
        assert_eq\!(compute_count, 1);
    }

    #[test]
    fn different_area_is_cache_miss() {
        let mut cache = LayoutCache::new(100);
        let constraints = vec\![Constraint::Percentage(50)];

        let mut compute_count = 0;
        let compute = || {
            compute_count += 1;
            vec\![Rect::default()]
        };

        let key1 = LayoutCacheKey::new(Rect::new(0, 0, 80, 24), &constraints, Direction::Horizontal, None);
        let key2 = LayoutCacheKey::new(Rect::new(0, 0, 120, 40), &constraints, Direction::Horizontal, None);

        cache.get_or_compute(key1, compute);
        cache.get_or_compute(key2, compute);

        assert_eq\!(compute_count, 2);
    }

    #[test]
    fn different_constraints_is_cache_miss() {
        let mut cache = LayoutCache::new(100);
        let area = Rect::new(0, 0, 80, 24);

        let mut compute_count = 0;

        let key1 = LayoutCacheKey::new(area, &[Constraint::Percentage(50)], Direction::Horizontal, None);
        let key2 = LayoutCacheKey::new(area, &[Constraint::Percentage(30)], Direction::Horizontal, None);

        cache.get_or_compute(key1, || { compute_count += 1; vec\![] });
        cache.get_or_compute(key2, || { compute_count += 1; vec\![] });

        assert_eq\!(compute_count, 2);
    }

    #[test]
    fn invalidation_clears_cache() {
        let mut cache = LayoutCache::new(100);
        let key = LayoutCacheKey::new(
            Rect::new(0, 0, 80, 24),
            &[Constraint::Fill],
            Direction::Horizontal,
            None,
        );

        let mut compute_count = 0;
        let compute = || { compute_count += 1; vec\![] };

        cache.get_or_compute(key, compute);
        cache.invalidate_all();
        cache.get_or_compute(key, compute);

        assert_eq\!(compute_count, 2);
    }

    #[test]
    fn intrinsics_affect_cache_key() {
        let mut cache = LayoutCache::new(100);
        let area = Rect::new(0, 0, 80, 24);
        let constraints = vec\![Constraint::FitContent];

        let mut compute_count = 0;

        let intrinsics1 = vec\![SizeConstraints { min: Size::new(10, 1), preferred: Size::new(20, 1), max: None }];
        let intrinsics2 = vec\![SizeConstraints { min: Size::new(10, 1), preferred: Size::new(30, 1), max: None }];

        let key1 = LayoutCacheKey::new(area, &constraints, Direction::Horizontal, Some(&intrinsics1));
        let key2 = LayoutCacheKey::new(area, &constraints, Direction::Horizontal, Some(&intrinsics2));

        cache.get_or_compute(key1, || { compute_count += 1; vec\![] });
        cache.get_or_compute(key2, || { compute_count += 1; vec\![] });

        assert_eq\!(compute_count, 2); // Different intrinsics = different keys
    }

    #[test]
    fn lru_eviction_works() {
        let mut cache = LayoutCache::new(2);

        let k1 = LayoutCacheKey::new(Rect::new(0, 0, 10, 10), &[], Direction::Horizontal, None);
        let k2 = LayoutCacheKey::new(Rect::new(0, 0, 20, 20), &[], Direction::Horizontal, None);
        let k3 = LayoutCacheKey::new(Rect::new(0, 0, 30, 30), &[], Direction::Horizontal, None);

        cache.get_or_compute(k1, || vec\![]);
        cache.get_or_compute(k2, || vec\![]);
        cache.get_or_compute(k1, || panic\!("k1 should hit"));
        cache.get_or_compute(k3, || vec\![]); // Evicts k2 (least recently used)

        assert_eq\!(cache.entries.len(), 2);
        assert\!(cache.entries.contains_key(&k1));
        assert\!(cache.entries.contains_key(&k3));
        assert\!(\!cache.entries.contains_key(&k2)); // Evicted
    }
}
