```rust
use criterion::{criterion_group, criterion_main, Criterion, BenchmarkId};

fn bench_layout_cache(c: &mut Criterion) {
    let mut group = c.benchmark_group("layout_cache");

    let constraints: Vec<Constraint> = (0..10).map(|_| Constraint::Percentage(10)).collect();
    let area = Rect::new(0, 0, 120, 40);

    // Uncached layout
    group.bench_function("uncached", |b| {
        let layout = Layout::horizontal().constraints(constraints.clone());
        b.iter(|| layout.split(area));
    });

    // Cached layout (hit)
    group.bench_function("cached_hit", |b| {
        let layout = Layout::horizontal().constraints(constraints.clone());
        let mut cache = LayoutCache::new(100);
        // Warm up cache
        layout.split_cached(area, &mut cache);

        b.iter(|| layout.split_cached(area, &mut cache));
    });

    // Cache key computation
    group.bench_function("key_computation", |b| {
        b.iter(|| {
            LayoutCacheKey::new(area, &constraints, Direction::Horizontal, None)
        });
    });

    group.finish();
}

criterion_group\!(benches, bench_layout_cache);
criterion_main\!(benches);
